const AutomationDialog = document.getElementById('automation-settings-dialog');
const AutomationMenu = document.getElementById('automation-settings');
const CloseAutomation = document.getElementById('close-automation-settings');
const KeyboxAutoToggle = document.getElementById('keybox-auto-toggle');
const SecurityPatchAutoToggle = document.getElementById('security-patch-auto-toggle');
const KeyboxAutoSourceGrid = document.getElementById('keybox-auto-source-grid');
const KeyboxIntervalGrid = document.getElementById('keybox-interval-grid');
const CurrentInterval = document.getElementById('current-interval');
const IntervalCustomInput = document.getElementById('interval-custom-input');
const IntervalUnitToggle = document.getElementById('interval-unit-toggle');
const IntervalCustomSet = document.getElementById('interval-custom-set');
const FetchKeyboxNow = document.getElementById('fetch-keybox-now');
const SetPatchNow = document.getElementById('set-patch-now');

const AUTO_CONFIG_PATH = '/data/adb/ommega/ommegadata/auto_config';

async function loadAutoConfig() {
  try {
    const {errno: err, stdout: content} = await _(`cat ${AUTO_CONFIG_PATH} 2>/dev/null`);
    if (err !== 0) {
      setDefaultConfig();
      return;
    }
    const config = JSON.parse(content);
    KeyboxAutoToggle.querySelector('.toggle-track').classList.toggle('active', config.keyboxAuto || false);
    SecurityPatchAutoToggle.querySelector('.toggle-track').classList.toggle('active', config.patchAuto || false);
    
    const activeSource = KeyboxAutoSourceGrid.querySelector(`.source-card[data-value="${config.keyboxSource || 'yurikey'}"]`);
    if (activeSource) {
      KeyboxAutoSourceGrid.querySelectorAll('.source-card').forEach(card => card.classList.remove('active'));
      activeSource.classList.add('active');
    }
    
    updateIntervalDisplay(config.keyboxInterval || 86400);
    const activeInterval = KeyboxIntervalGrid.querySelector(`.interval-chip[data-seconds="${config.keyboxInterval || 86400}"]`);
    if (activeInterval) {
      KeyboxIntervalGrid.querySelectorAll('.interval-chip').forEach(chip => chip.classList.remove('active'));
      activeInterval.classList.add('active');
    }
  } catch {
    setDefaultConfig();
  }
}

function setDefaultConfig() {
  KeyboxAutoToggle.querySelector('.toggle-track').classList.remove('active');
  SecurityPatchAutoToggle.querySelector('.toggle-track').classList.remove('active');
  KeyboxAutoSourceGrid.querySelectorAll('.source-card').forEach(card => card.classList.remove('active'));
  const defaultSource = KeyboxAutoSourceGrid.querySelector('.source-card[data-value="yurikey"]');
  if (defaultSource) defaultSource.classList.add('active');
  updateIntervalDisplay(86400);
}

async function saveAutoConfig(config) {
  const existingConfig = await getCurrentConfig();
  const newConfig = {...existingConfig, ...config};
  const configJson = JSON.stringify(newConfig);
  const tmpFile = `/tmp/auto_config_${Math.random().toString(36).substr(2, 9)}`;
  await _(`echo "${configJson.replace(/"/g, '\\"')}" > "${tmpFile}" && mkdir -p /data/adb/ommega && cat "${tmpFile}" > /data/adb/ommega/ommegadata/auto_config && rm -f "${tmpFile}" && chmod 644 /data/adb/ommega/ommegadata/auto_config`);
}

async function getCurrentConfig() {
  try {
    const {errno: err, stdout: content} = await _(`cat /data/adb/ommega/ommegadata/auto_config 2>/dev/null`);
    if (err !== 0) return {};
    return JSON.parse(content);
  } catch {
    return {};
  }
}

function updateIntervalDisplay(seconds) {
  let display;
  if (seconds < 3600) {
    display = `${Math.floor(seconds / 60)} min`;
  } else if (seconds < 86400) {
    display = `${Math.floor(seconds / 3600)} hr`;
  } else {
    display = `${Math.floor(seconds / 86400)} day`;
  }
  CurrentInterval.textContent = display;
}

AutomationMenu.addEventListener('click', async () => {
  await loadAutoConfig();
  AutomationDialog.show();
});

CloseAutomation.addEventListener('click', () => {
  AutomationDialog.close();
});

KeyboxAutoToggle.addEventListener('click', async () => {
  const track = KeyboxAutoToggle.querySelector('.toggle-track');
  const isActive = track.classList.toggle('active');
  await saveAutoConfig({keyboxAuto: isActive});
  if (isActive) {
    y('prompt_keybox_auto_enabled');
  }
});

SecurityPatchAutoToggle.addEventListener('click', async () => {
  const track = SecurityPatchAutoToggle.querySelector('.toggle-track');
  const isActive = track.classList.toggle('active');
  await saveAutoConfig({patchAuto: isActive});
  if (isActive) {
    y('prompt_patch_auto_enabled');
  }
});

KeyboxAutoSourceGrid.addEventListener('click', async (e) => {
  const card = e.target.closest('.source-card');
  if (!card || card.hasAttribute('data-action')) return;
  
  KeyboxAutoSourceGrid.querySelectorAll('.source-card').forEach(c => c.classList.remove('active'));
  card.classList.add('active');
  
  const source = card.getAttribute('data-value');
  await saveAutoConfig({keyboxSource: source});
  y('prompt_source_selected');
});

KeyboxIntervalGrid.addEventListener('click', async (e) => {
  const chip = e.target.closest('.interval-chip');
  if (!chip) return;
  
  KeyboxIntervalGrid.querySelectorAll('.interval-chip').forEach(c => c.classList.remove('active'));
  chip.classList.add('active');
  
  const seconds = parseInt(chip.getAttribute('data-seconds'));
  updateIntervalDisplay(seconds);
  await saveAutoConfig({keyboxInterval: seconds});
  y('prompt_interval_set');
});

IntervalUnitToggle.addEventListener('click', (e) => {
  const btn = e.target.closest('.unit-btn');
  if (!btn) return;
  
  IntervalUnitToggle.querySelectorAll('.unit-btn').forEach(b => b.classList.remove('selected'));
  btn.classList.add('selected');
});

IntervalCustomSet.addEventListener('click', async () => {
  const value = parseInt(IntervalCustomInput.value);
  if (isNaN(value) || value <= 0) {
    y('prompt_invalid_interval', false);
    return;
  }
  
  const unitBtn = IntervalUnitToggle.querySelector('.unit-btn.selected');
  const multiplier = parseInt(unitBtn.getAttribute('data-mult'));
  const seconds = value * multiplier;
  
  KeyboxIntervalGrid.querySelectorAll('.interval-chip').forEach(c => c.classList.remove('active'));
  updateIntervalDisplay(seconds);
  await saveAutoConfig({keyboxInterval: seconds});
  IntervalCustomInput.value = '';
  y('prompt_interval_set');
});

